        engineeringData: { blockDesign: "Inline-6, Closed-deck Aluminum block with cast iron cylinder liners. The TU2 revision of the legendary M57 successfully transitioned from a heavy cast iron block to an aluminum architecture, shedding significant weight over the front axle while utilizing ultra-durable cast iron liners to maintain immense cylinder strength. It is a masterpiece of diesel engineering.", crankshaft: "Forged Steel, massively over-engineered and supported by 7 main bearings. Inherently perfectly balanced.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "170A Valeo.", rotatingAssembly: { pistonConstruction: "Heavy-duty cast aluminum alloy featuring internal oil cooling galleries. Features a 17.0:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design.", intakePortFlow: "24-valve DOHC design. The intake ports feature aggressive swirl characteristics, heavily augmented by the problematic swirl flaps to improve low-RPM mixing.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Standard diesel duration. Driven by the incredibly robust front-mounted timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Tax Dodge Variant (Fleet). This specific model is tailored for markets with heavy taxes above certain power thresholds (often Belgium). It is mechanically 100% identical to the global 235hp version, simply rated at 211hp on paper. It features the groundbreaking Dynamic Performance Control (DPC) rear differential, a heavy torque-vectoring unit that physically overdrives the outer rear wheel during cornering, eliminating understeer." }, oilAndCooling: { oilSquirters: "Yes, high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven mechanical gear pump, highly reliable.", thermostatOpening: "88°C Mechanical thermostat. Highly prone to failing open.", oilCooler: "Heavy-duty integrated liquid-to-liquid heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection with CP3 High-Pressure Pump.", maxPressure: "1,600 Bar (Fuel Rail). The CP3 pump is legendary for its bulletproof reliability.", injectors: "6x Bosch Piezo Injectors." }, tuningLimits: { maxSafeTorqueStock: "750 Nm (The ZF 6HP28X handles this effortlessly).", maxSafePowerStock: "450 hp (The M57TU2 aluminum block and forged internals are virtually unbreakable).", maxSafeRPM: "4800 RPM", weakestLink: "Swirl Flaps (Engine Ingestion), Pressed-Steel Exhaust Manifold (Cracking), Thermostats (Cold running ruins DPF)." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch EDC16 (Highly tunable and deeply mapped by the aftermarket community)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the fatal swirl flap ingestion, exhaust leaks, and cooling failures inherent to the M57 engine.", parts: [ { category: "Swirl Flap Blanking Kit", brand: "Victor Reinz / Billet", note: "CRITICAL: Remove the factory plastic flaps before they break and destroy the engine." }, { category: "Cast Iron Exhaust Manifold", brand: "BGA / Aftermarket", note: "CRITICAL: Replaces the cracking factory pressed-steel unit." }, { category: "Vibration Damper", brand: "Corteco", note: "CRITICAL: Proactive replacement prevents sudden serpentine belt loss." }, { category: "Main & EGR Thermostats", brand: "Mahle / Behr", note: "CRITICAL: Replaces failing units to allow engine to reach 90°C and trigger DPF regen." }, { category: "Glow Plug & Relay Kit", brand: "Bosch / Beru", note: "Essential for reliable cold starts and DPF regeneration cycles." }, { category: "ZF 6HP Transmission Pan/Filter", brand: "ZF Genuine", note: "CRITICAL: Change fluid, pan, and Mechatronic seals every 80k km." }, { category: "Front Thrust Arms (Control Arms)", brand: "Lemförder", note: "Fixes severe E71 braking shimmy caused by the massive chassis weight." }, { category: "DPC Differential Fluid Kit", brand: "Castrol", note: "Requires specific fluids for all 3 chambers of the torque-vectoring rear diff." } ] },
