        sisterModels: [ { name: "BMW 330d (E90 Fleet Edition)", note: "The E90 330d Fleet Edition utilized the exact same artificially restricted M57 engine. The immense DIY knowledge base regarding swirl flap deletes, cast manifold upgrades, and tuning translates perfectly to this X6." } ],
        tuningPotential: [
          { stage: "Stage 1 (Bootmod3 / MHD Flash)", power: "290 - 310 hp", notes: "THE ULTIMATE SLEEPER UPGRADE. Because this Fleet Edition is mechanically identical to the standard 235hp model, a simple OBD software flash safely unlocks a massive amount of hidden power. It bypasses the artificial restriction, jumping from 211hp to roughly 300hp and a staggering 650Nm of torque. This completely transforms the heavy E71 X6. The factory ZF 6-speed handles this torque easily.", zeroToHundred: "6.8s", hundredToTwoHundred: "19.5s" },
          { stage: "Stage 2 (DPF/EGR Delete & Tune)", power: "320 - 340 hp", notes: "Requires mapping out the emissions systems, installing a straight-through downpipe, and upgrading the intercooler. Note: This renders the car non-road legal in most areas but completely eliminates all DPF and EGR reliability issues. The engine breathes far better and the turbo spools instantly.", zeroToHundred: "6.4s", hundredToTwoHundred: "18.0s" },
          { stage: "Stage 3 (Upgraded Hybrid Turbo)", power: "400 - 450+ hp", notes: "Requires upgrading the factory Garrett turbo to a hybrid unit, upgrading to an R90 high-pressure fuel pump, and installing a massive front-mount intercooler. The M57 aluminum block and forged internals can handle 450hp safely, transforming the X6 into an absolute diesel rocket.", zeroToHundred: "5.5s", hundredToTwoHundred: "14.5s" }
        ],
