        engineeringData: { blockDesign: "Inline-6, Closed-deck Aluminum block with wire-arc sprayed cylinder liners. The N57 represents a major modernization over the older M57. It is lighter, more efficient, and much quieter. However, BMW made the highly controversial decision to move the timing chain to the rear of the block, creating a massive maintenance liability.", crankshaft: "Forged Steel, supported by 7 main bearings. Inherently perfectly balanced.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "180A Valeo.", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy featuring internal oil cooling galleries. Features a 16.5:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design.", intakePortFlow: "24-valve DOHC design. The plastic intake manifold integrates the swirl flaps directly, meaning they cannot be easily blanked off without replacing the entire manifold like the older M57.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Standard diesel duration. Driven by the notorious rear-mounted timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Tax Dodge Variant (Fleet). This specific model is tailored for markets with heavy taxes above certain power thresholds (often Belgium). It is mechanically 100% identical to the global 245hp version, simply rated at 211hp on paper to slide under penalty brackets. This makes it the ultimate sleeper once tuned. It retains the groundbreaking Dynamic Performance Control (DPC) rear torque-vectoring differential." }, oilAndCooling: { oilSquirters: "Yes, high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement map-controlled pump.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Heavy-duty integrated liquid-to-liquid heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection with CP4 High-Pressure Pump.", maxPressure: "1,800 Bar (Fuel Rail). The CP4 pump is highly prone to catastrophic internal failure if fuel lubricity is poor.", injectors: "6x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "750 Nm (The ZF 8HP70 handles this effortlessly).", maxSafePowerStock: "400 hp (The N57 aluminum block and forged internals are incredibly strong).", maxSafeRPM: "4800 RPM", weakestLink: "Timing Chain (Snapping), CP4 Fuel Pump (Implosion), EGR Cooler (Fire Risk), Vibration Damper (Tears)." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch EDC17 (Highly tunable and deeply mapped by the aftermarket community)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the fatal timing chain snap, CP4 pump implosion, and EGR fires inherent to the N57 engine.", parts: [ { category: "Timing Chain Kit", brand: "Genuine BMW / IWIS", note: "CRITICAL: Proactive replacement around 150k km saves the engine from destruction." }, { category: "EGR Cooler", brand: "BorgWarner / Genuine BMW", note: "CRITICAL: Ensure the latest revised unit is installed to prevent fires." }, { category: "CP3 Fuel Pump Retrofit Kit", brand: "Aftermarket Billet", note: "CRITICAL: Replaces the ticking time-bomb CP4 pump with a reliable CP3." }, { category: "Vibration Damper", brand: "Corteco", note: "CRITICAL: Proactive replacement prevents sudden serpentine belt loss." }, { category: "Diesel Fuel Filter", brand: "Mann Filter", note: "Replace every 30k km to protect the fragile CP4 pump." }, { category: "Intake Manifold Gaskets", brand: "Elring", note: "Required when performing mandatory Walnut Blasting." }, { category: "ZF 8HP Transmission Pan/Filter", brand: "ZF Genuine", note: "CRITICAL: Change fluid and pan religiously every 80k km." }, { category: "Front Thrust Arms (Control Arms)", brand: "Lemförder", note: "Fixes severe E71 braking shimmy caused by the massive chassis weight." } ] },
