          { partName: "Front Thrust Arms (Control Arms)", category: "Suspension", oem: { brand: "BMW Genuine", code: "31126773949", approxPrice: "280 EUR" }, crossRef: { brand: "Lemförder", code: "34757 01", approxPrice: "130 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=31126773949", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=31126773949" }, note: "Fixes severe E71 braking shimmy." }
