            { interval: "200,000 km", timeLimit: "Unlimited", task: "Vibration Damper Replacement", details: "Proactively replace the massive main crankshaft pulley before the rubber core shears and destroys the serpentine belt.", parts: ["Corteco Damper", "Stretch Bolts"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "350 EUR" }
