        engineeringData: { blockDesign: "Inline-6, Closed-deck Aluminum block with wire-arc sprayed cylinder liners. The N57 represents a major modernization over the older M57. It is lighter, more efficient, and much quieter. However, BMW made the highly controversial decision to move the timing chain to the rear of the block, creating a massive maintenance liability.", crankshaft: "Forged Steel, supported by 7 main bearings. Inherently perfectly balanced.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "180A Valeo.", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy featuring internal oil cooling galleries. Features a 16.5:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design.", intakePortFlow: "24-valve DOHC design. The plastic intake manifold integrates the swirl flaps directly, meaning they cannot be easily blanked off without replacing the entire manifold like the older M57.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Standard diesel duration. Driven by the notorious rear-mounted timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Sequential Twin-Turbo, Rear Timing Chain, & ZF 8-Speed. The LCI E71 X6 40d introduced the pinnacle of N57 performance, delivering a massive 306hp. While it brought massive improvements in refinement, sequential turbo response, and was paired with the incredible new ZF 8-speed automatic, it introduced the two fatal flaws of the N-series diesel era: the snapping rear timing chain and the imploding CP4 fuel pump." }, oilAndCooling: { oilSquirters: "Yes, high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement map-controlled pump.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Heavy-duty integrated liquid-to-liquid heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection with CP4 High-Pressure Pump.", maxPressure: "2,000 Bar (Fuel Rail). The CP4 pump is highly prone to catastrophic internal failure if fuel lubricity is poor.", injectors: "6x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "750 Nm (The ZF 8HP70 handles this effortlessly).", maxSafePowerStock: "450 hp (The N57 Twin-Turbo aluminum block and forged internals are incredibly strong).", maxSafeRPM: "4800 RPM", weakestLink: "Timing Chain (Snapping), CP4 Fuel Pump (Implosion), Vacuum Hoses (Turbo Staging), EGR Cooler (Fire Risk), Vibration Damper (Tears)." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch EDC17 (Highly tunable and deeply mapped by the aftermarket community)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the fatal timing chain snap, CP4 pump implosion, extreme vacuum failures, and EGR fires inherent to the N57 Twin-Turbo engine.", parts: [ { category: "Timing Chain Kit", brand: "Genuine BMW / IWIS", note: "CRITICAL: Proactive replacement around 150k km saves the engine from destruction." }, { category: "Vacuum Hose Kit", brand: "Silicone Aftermarket", note: "CRITICAL: Replaces rotting rubber lines to restore sharp sequential turbo staging." }, { category: "CP3 Fuel Pump Retrofit Kit", brand: "Aftermarket Billet", note: "CRITICAL: Replaces the ticking time-bomb CP4 pump with a reliable CP3." }, { category: "EGR Cooler", brand: "BorgWarner / Genuine BMW", note: "CRITICAL: Ensure the latest revised unit is installed to prevent fires." }, { category: "Vibration Damper", brand: "Corteco", note: "CRITICAL: Proactive replacement prevents sudden serpentine belt loss." }, { category: "Intake Manifold Gaskets", brand: "Elring", note: "Required when performing mandatory Walnut Blasting." }, { category: "ZF 8HP Transmission Pan/Filter", brand: "ZF Genuine", note: "CRITICAL: Change fluid and pan religiously every 80k km." }, { category: "Front Thrust Arms (Control Arms)", brand: "Lemförder", note: "Fixes severe E71 braking shimmy caused by the massive chassis weight." } ] },
