        engineeringData: { blockDesign: "Inline-6, Open-deck Aluminum block with cast iron cylinder liners. The N54 is legendary in the tuning community. While an open-deck design is usually weaker, BMW severely over-engineered the block webbing and used highly durable cast iron liners, making it capable of handling insane cylinder pressures that rival the legendary Toyota 2JZ.", crankshaft: "Forged Steel, massively over-engineered and supported by 7 main bearings. Inherently perfectly balanced.", pistonSpeed: "15.4 m/s @ 7000 RPM.", alternator: "180A Valeo.", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features a 10.2:1 compression ratio.", wristPinDiameter: "22 mm.", connectingRodLength: "145 mm.", rodBoltSize: "M9.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.62." }, cylinderHead: { combustionChamberVol: "Direct injection specific pent-roof design.", intakePortFlow: "24-valve DOHC design. Features Double-VANOS (variable valve timing) but notably DOES NOT feature Valvetronic (variable valve lift), using a traditional throttle body instead. This simplifies the head but slightly reduces efficiency compared to the newer N55.", valveSizes: "Intake: 31.4 mm / Exhaust: 28.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Highly variable via Double-VANOS.", lifterType: "Hydraulic bucket tappets.", specialFeature: "M Performance Power Kit (PPK) & DPC Vectoring. This specific variant comes factory-equipped with the BMW PPK software upgrade, pushing power from 306hp to 326hp and increasing cooling fan capacity. Furthermore, the E71 X6 introduced the groundbreaking Dynamic Performance Control (DPC) rear differential, a heavy torque-vectoring unit that physically overdrives the outer rear wheel during cornering, eliminating understeer and making the heavy SUV handle incredibly well." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement map-controlled pump.", thermostatOpening: "Electronically mapped by the ECU (ranges from 90°C to 105°C).", oilCooler: "Standard integrated liquid-to-liquid heat exchanger. (Prone to OFHG leaks)." }, fuelSystem: { systemType: "Bosch High Precision Direct Injection.", maxPressure: "200 Bar (Fuel Rail). The High-Pressure Fuel Pump (HPFP) is highly prone to failure.", injectors: "6x Piezo Injectors (MUST be upgraded to Index 12 for reliability)." }, tuningLimits: { maxSafeTorqueStock: "700 Nm (The ZF 6HP28X handles this perfectly).", maxSafePowerStock: "600+ hp (The N54 block and forged internals are legendary for holding massive power).", maxSafeRPM: "7000 RPM", weakestLink: "Injectors (Leaking ruins engine), HPFP (Fails constantly), Electric Water Pump (Sudden failure), Charge Pipe (Explodes), Wastegates (Rattle)." }, electrical: { coils: "Individual Coil Pack system (Bosch/Eldor).", ecu: "Siemens MSD80/MSD81 (Highly tunable and deeply mapped by the aftermarket community)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the fatal injector leaks, HPFP failures, water pump stranding, and belt ingestion inherent to the legendary N54 engine.", parts: [ { category: "Index 12 Injectors", brand: "Genuine BMW", note: "CRITICAL: Upgrade immediately to prevent engine cylinder wash-down." }, { category: "High-Pressure Fuel Pump (HPFP)", brand: "Genuine BMW / Bosch", note: "CRITICAL: Common failure causing long cranks and limp mode." }, { category: "Electric Water Pump & Thermostat", brand: "Pierburg / VDO", note: "CRITICAL: Proactive replacement at 100k km prevents sudden overheating." }, { category: "Aluminum Charge Pipe", brand: "VRSF / FTP", note: "CRITICAL: Prevents factory plastic pipe explosion under boost." }, { category: "Oil Filter Housing Gasket (OFHG)", brand: "Genuine BMW", note: "CRITICAL: Fixes oil leak that causes fatal serpentine belt ingestion." }, { category: "Valve Cover & PCV Valve", brand: "Genuine BMW", note: "Fixes vacuum leaks, oil leaks, and PCV whistling." }, { category: "ZF 6HP Transmission Pan & Mechatronic Seals", brand: "ZF Genuine", note: "CRITICAL: Change fluid, pan, and all internal rubber sleeve seals every 80k km." }, { category: "Front Thrust Arms (Control Arms)", brand: "Lemförder", note: "Fixes severe E71 braking shimmy caused by the massive chassis weight." } ] },
