            { interval: "40,000 km", timeLimit: "4 years", task: "Spark Plug Replacement", details: "Twin-turbo N54s eat spark plugs rapidly. Replace to prevent severe misfires under heavy boost.", parts: ["6x NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" },
            { interval: "80,000 km", timeLimit: "8 years", task: "Ignition Coil Replacement", details: "Proactively replace coil packs to maintain perfectly smooth power delivery.", parts: ["6x Eldor/Bosch Coils"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "240 EUR" }
