            { interval: "80,000 km", timeLimit: "6 years", task: "Serpentine Belts & Tensioners", details: "Replace the main drive belt and tensioner. A snapped belt gets ingested into the engine.", parts: ["Continental Kit"], importance: "High", laborDifficulty: "Easy", estimatedCost: "120 EUR" }
