        sisterModels: [ { name: "BMW 335i (E90 LCI)", note: "The E90 LCI 335i utilized the exact same N55 Twin-Scroll engine. The immense DIY knowledge base regarding electric water pumps, charge pipes, and Valvetronic issues translates perfectly to this X6." } ],
        tuningPotential: [
          { stage: "Stage 1 (Bootmod3 / MHD Flash)", power: "360 - 380 hp", notes: "THE ULTIMATE UPGRADE. The N55 is incredibly responsive to software. A simple OBD flash safely unlocks a massive amount of hidden power, jumping from 306hp to roughly 370hp and 520Nm of torque. This completely transforms the heavy E71 X6. The factory ZF 8-speed transmission handles this effortlessly.", zeroToHundred: "5.7s", hundredToTwoHundred: "15.0s" },
          { stage: "Stage 2 (Downpipes & Tune)", power: "390 - 410 hp", notes: "Requires a high-flow or catless downpipe, an upgraded aluminum charge pipe (MANDATORY), and a larger front-mount intercooler. The exhaust note becomes incredibly aggressive. The N55 block handles this power well, providing a massive wave of mid-range torque.", zeroToHundred: "5.3s", hundredToTwoHundred: "13.2s" },
          { stage: "Stage 3 (Upgraded Turbo)", power: "450 - 500 hp", notes: "Requires upgrading the factory turbo to a hybrid unit (e.g., Pure Stage 2), upgrading the high-pressure fuel pump, and full bolt-ons. Unlike the N54, the N55 cast crankshaft and weaker rods mean that pushing past 500hp is highly dangerous and risks spinning a rod bearing or bending a rod.", zeroToHundred: "4.8s", hundredToTwoHundred: "11.5s" }
        ],
        tuningGraphData: { stock: { hp: 306, nm: 400 }, stage1: { hp: 370, nm: 520 }, stage2: { hp: 400, nm: 560 }, stage3: { hp: 480, nm: 650 } },
