        sisterModels: [ { name: "BMW 335i (E90 US Market)", note: "The legendary E90 335i utilized the exact same N54 Twin-Turbo engine in the US. The immense DIY knowledge base regarding Index 12 injectors, HPFP warranties, charge pipes, and massive single-turbo conversions translates perfectly to this X6." } ],
        tuningPotential: [
          { stage: "Stage 1 (Bootmod3 / MHD Flash)", power: "360 - 380 hp", notes: "THE ULTIMATE UPGRADE. The N54 is globally renowned as the 'German 2JZ'. A simple OBD software flash safely unlocks a massive amount of hidden power, jumping from 300hp to roughly 360hp and 500Nm of torque. This completely transforms the heavy E71 X6. The factory ZF 6-speed transmission handles this effortlessly.", zeroToHundred: "5.8s", hundredToTwoHundred: "15.0s" },
          { stage: "Stage 2 (Downpipes & Tune)", power: "400 - 430 hp", notes: "Requires high-flow or catless downpipes, an upgraded aluminum charge pipe (MANDATORY), and a larger front-mount intercooler. The exhaust note becomes incredibly aggressive. The forged N54 block handles this power effortlessly. At this level, fresh Index 12 injectors and a healthy HPFP are absolutely critical.", zeroToHundred: "5.3s", hundredToTwoHundred: "12.8s" },
          { stage: "Stage 3 (Upgraded Twin Turbos or Single Turbo)", power: "550 - 650+ hp", notes: "Requires upgrading the factory Mitsubishi turbos to hybrid units (or a massive single turbo conversion), upgrading the fueling system (often adding Port Injection), and full bolt-ons. The N54 block and forged internals can handle 600hp safely on stock internals with E85 fuel, transforming the X6 into an absolute supercar-killing rocket.", zeroToHundred: "4.5s", hundredToTwoHundred: "10.0s" }
        ],
        tuningGraphData: { stock: { hp: 300, nm: 407 }, stage1: { hp: 360, nm: 500 }, stage2: { hp: 420, nm: 550 }, stage3: { hp: 600, nm: 750 } },
