        engineeringData: { blockDesign: "Inline-6, Open-deck Aluminum block with cast iron cylinder liners. The N55 was designed to be vastly more reliable day-to-day than the high-maintenance N54 it replaced. While the open-deck design is strong, it uses a cast crankshaft and weaker rods than the N54, meaning it cannot handle extreme 600+ hp tuning safely.", crankshaft: "Cast Iron, supported by 7 main bearings.", pistonSpeed: "15.4 m/s @ 7000 RPM.", alternator: "180A Valeo.", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features a 10.2:1 compression ratio.", wristPinDiameter: "22 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M9.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.61." }, cylinderHead: { combustionChamberVol: "Direct injection specific pent-roof design.", intakePortFlow: "24-valve DOHC design. The N55 crucially added Valvetronic (variable valve lift) acting as the throttle. This vastly improves throttle response and fuel efficiency, but adds a highly complex eccentric shaft that can wear out.", valveSizes: "Intake: 32.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Highly variable via Double-VANOS and Valvetronic.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Tax Dodge Variant (CN). This specific model was artificially detuned to 282hp to avoid heavy engine displacement and power-based luxury taxes in the Chinese market. It features exactly the same turbo and internal components as the 306hp global version, making it the ultimate blank canvas for software tuning. It also retains the legendary DPC torque-vectoring rear differential." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement map-controlled pump.", thermostatOpening: "Electronically mapped by the ECU (ranges from 90°C to 105°C).", oilCooler: "Standard integrated liquid-to-liquid heat exchanger. (Prone to OFHG leaks)." }, fuelSystem: { systemType: "Bosch High Precision Direct Injection.", maxPressure: "200 Bar (Fuel Rail). The N55 HPFP is significantly more robust than the N54 version.", injectors: "6x Bosch Solenoid Injectors (Vastly more reliable than N54 Piezo units)." }, tuningLimits: { maxSafeTorqueStock: "500 Nm (The ZF 8HP45 transmission is maxed out here).", maxSafePowerStock: "450 hp (The N55 cast crank and weaker rods limit safe tuning compared to the N54).", maxSafeRPM: "7000 RPM", weakestLink: "Charge Pipe (Explodes), Electric Water Pump (Sudden failure), OFHG Oil Leak (Belt Ingestion), Valvetronic Wear." }, electrical: { coils: "Individual Coil Pack system (Bosch/Eldor).", ecu: "Bosch MEVD17.2 (Highly tunable and deeply mapped by the aftermarket community)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the fatal water pump stranding, exploding charge pipe, and belt ingestion inherent to the N55 engine.", parts: [ { category: "Electric Water Pump & Thermostat", brand: "Pierburg / VDO", note: "CRITICAL: Proactive replacement at 100k km prevents sudden overheating." }, { category: "Aluminum Charge Pipe", brand: "VRSF / FTP", note: "CRITICAL: Prevents factory plastic pipe explosion under boost." }, { category: "Oil Filter Housing Gasket (OFHG)", brand: "Genuine BMW", note: "CRITICAL: Fixes oil leak that causes fatal serpentine belt ingestion." }, { category: "Valvetronic Eccentric Shaft Sensor & Motor", brand: "Genuine BMW / VDO", note: "Common failure causing limp mode and rough idle." }, { category: "Valve Cover & PCV Valve", brand: "Genuine BMW", note: "Fixes vacuum leaks, oil leaks, and PCV whistling." }, { category: "Spark Plugs", brand: "NGK SILZKBR8D8S", note: "Replace strictly every 50k km on tuned N55 engines." }, { category: "ZF 8HP Transmission Pan/Filter", brand: "ZF Genuine", note: "CRITICAL: Change fluid and pan religiously every 80k km." }, { category: "Front Thrust Arms (Control Arms)", brand: "Lemförder", note: "Fixes severe E71 braking shimmy caused by the massive chassis weight." } ] },
