            { interval: "4 Years", timeLimit: "4 years", task: "A/C System Service", details: "Recover and recharge the A/C refrigerant.", parts: ["R134a"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" }
