        engineeringData: { blockDesign: "V8 (90-degree), Closed-deck Aluminum block with cast iron cylinder liners. The N63 introduced the revolutionary 'Hot-V' configuration, placing the twin turbos inside the valley between the cylinders. This drastically reduces exhaust travel distance, practically eliminating turbo lag. However, this design traps unimaginable heat, destroying every plastic and rubber component nearby and earning it a reputation as one of the most problematic engines ever.", crankshaft: "Forged Steel, supported by 5 main bearings. Features a cross-plane design.", pistonSpeed: "15.4 m/s @ 6500 RPM.", alternator: "220A Valeo.", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features a 10.0:1 compression ratio.", wristPinDiameter: "22 mm.", connectingRodLength: "143 mm.", rodBoltSize: "M10.", crankMainJournal: "70.0 mm.", crankRodJournal: "48.0 mm.", rodRatio: "1.73." }, cylinderHead: { combustionChamberVol: "Pent-roof design with centrally located Piezo injectors.", intakePortFlow: "32-valve DOHC design. The intake manifolds are uniquely placed on the OUTSIDE of the cylinder banks, while the exhaust ports face the INSIDE 'V'. Features Double-VANOS (variable valve timing) but notably DOES NOT feature Valvetronic.", valveSizes: "Intake: 33.0 mm / Exhaust: 29.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Highly variable via Double-VANOS.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Tax Dodge Detune & DPC Vectoring. This specific model is tailored for the Chinese market. It is mechanically 100% identical to the global 408hp version, simply rated at 349hp on paper to slide under strict engine power and displacement taxes. Furthermore, the E71 X6 introduced the groundbreaking Dynamic Performance Control (DPC) rear differential, a heavy torque-vectoring unit that physically overdrives the outer rear wheel during cornering, eliminating understeer." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement map-controlled pump.", thermostatOpening: "Electronically mapped by the ECU (ranges from 90°C to 105°C).", oilCooler: "Massive integrated liquid-to-liquid heat exchanger." }, fuelSystem: { systemType: "Bosch High Precision Direct Injection.", maxPressure: "200 Bar (Fuel Rail). Uses two mechanical high-pressure fuel pumps.", injectors: "8x Piezo Injectors (MUST be upgraded to Index 11/12 to prevent hydrolock)." }, tuningLimits: { maxSafeTorqueStock: "750 Nm (The ZF 6HP28X transmission handles this perfectly).", maxSafePowerStock: "550 hp (The N63 block handles this safely, but high heat guarantees component failure).", maxSafeRPM: "6500 RPM", weakestLink: "Valve Stem Seals (Massive oil burning), Injectors (Hydrolock), Timing Chains (Stretch/Snap), Hot-V Cooling Lines (Fire risk), OFHG Oil Leak (Belt Ingestion)." }, electrical: { coils: "Individual Coil Pack system (Bosch).", ecu: "Dual Bosch MEVD17.2 (Highly tunable via OBD)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent catastrophic engine hydrolock, fires, timing chain failure, and oil burning on the notoriously fragile N63 V8 engine.", parts: [ { category: "Valve Stem Seal Kit", brand: "Elring / Victor Reinz", note: "CRITICAL: Fixes massive blue smoke. Must use AGA Tools." }, { category: "Index 11/12 Injectors", brand: "Genuine BMW", note: "CRITICAL: Upgrade immediately to prevent engine hydrolock." }, { category: "Hot-V Turbo Cooling Lines", brand: "Genuine BMW / Billet", note: "CRITICAL: Plastic 'T' fittings crack. Upgrade to billet aluminum." }, { category: "Timing Chain Kit", brand: "Genuine BMW / IWIS", note: "CRITICAL: Replaces weak original chains to prevent snapping." }, { category: "Oil Filter Housing Gasket (OFHG)", brand: "Genuine BMW", note: "CRITICAL: Fixes oil leak that causes fatal belt ingestion." }, { category: "105Ah AGM Battery", brand: "Varta / Genuine BMW", note: "CRITICAL: The hot-V cooling fans kill batteries rapidly." }, { category: "ZF 6HP Transmission Pan & Mechatronic Seals", brand: "ZF Genuine", note: "CRITICAL: Change fluid, pan, and all internal rubber sleeve seals every 80k km." }, { category: "Front Thrust Arms (Control Arms)", brand: "Lemförder", note: "Fixes severe E71 braking shimmy caused by the massive chassis weight." } ] },
