            { interval: "80,000 km", timeLimit: "Unlimited", task: "Hot-V Coolant Line Overhaul", details: "CRITICAL: Replace the plastic/rubber coolant 'T-fittings' and turbo lines before they crack and cause an engine fire. Upgrade to billet aluminum fittings if possible.", parts: ["Coolant Line Kit", "Billet Tees"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "400 EUR" },
            { interval: "120,000 km", timeLimit: "Unlimited", task: "Valve Stem Seal Replacement", details: "CRITICAL: When the engine starts smoking blue out the exhaust after idling, you MUST replace the valve stem seals using the AGA tool method.", parts: ["Elring Seal Kit", "AGA Tool Rental"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "2,000 - 3,000 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Timing Chain Replacement", details: "CRITICAL: The original timing chains stretch under the V8 torque. Proactive replacement is highly recommended to prevent piston-to-valve contact.", parts: ["IWIS Chain Kit"], importance: "High", laborDifficulty: "Expert", estimatedCost: "2,500 - 3,500 EUR" },
            { interval: "80,000 km", timeLimit: "Unlimited", task: "Intake Manifold Walnut Blasting", details: "Remove the intake manifolds and blast the thick carbon sludge from the intake ports caused by direct injection.", parts: ["Intake Gaskets", "Labor"], importance: "High", laborDifficulty: "Expert", estimatedCost: "500 EUR" },
            { interval: "30,000 km", timeLimit: "3 years", task: "Spark Plug Replacement", details: "CRITICAL: The tuned M engine eats spark plugs rapidly. Replace frequently to prevent severe misfires under heavy boost.", parts: ["8x NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" },
            { interval: "80,000 km", timeLimit: "8 years", task: "Ignition Coil Replacement", details: "Proactively replace coil packs to maintain perfectly smooth power delivery.", parts: ["8x Eldor/Bosch Coils"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "300 EUR" }
