        engineeringData: { blockDesign: "V8 (90-degree), Closed-deck Aluminum block with wire-arc sprayed cylinder liners. The S63 introduced the revolutionary 'Hot-V' configuration, placing the twin turbos inside the valley between the cylinders. This drastically reduces exhaust travel distance, practically eliminating turbo lag. However, this design traps unimaginable heat, destroying every plastic and rubber component nearby and earning it a reputation as one of the most demanding engines to maintain.", crankshaft: "Forged Steel, supported by 5 main bearings. Features a cross-plane design.", pistonSpeed: "15.4 m/s @ 6500 RPM.", alternator: "220A Valeo.", rotatingAssembly: { pistonConstruction: "Forged aluminum alloy. Optimized for extreme cylinder pressures.", wristPinDiameter: "22 mm.", connectingRodLength: "143 mm.", rodBoltSize: "M10.", crankMainJournal: "70.0 mm.", crankRodJournal: "48.0 mm.", rodRatio: "1.73." }, cylinderHead: { combustionChamberVol: "Pent-roof design with centrally located Piezo injectors.", intakePortFlow: "32-valve DOHC design. The intake manifolds are uniquely placed on the OUTSIDE of the cylinder banks, while the exhaust ports face the INSIDE 'V'. Features Double-VANOS (variable valve timing) but notably DOES NOT feature Valvetronic on this early S63 version.", valveSizes: "Intake: 33.0 mm / Exhaust: 29.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Highly variable via Double-VANOS.", lifterType: "Hydraulic bucket tappets.", specialFeature: "US Spec Rating & DPC Vectoring. This specific variant was tailored for the US market, officially rated at 547hp (SAE) to meet US emissions and marketing standards, though mechanically identical to the 555hp EU version. The S63 utilizes an exhaust manifold that crosses over the engine, pulsing exhaust gases from cylinders on opposite sides directly into the twin-scroll turbos, completely eliminating lag. Furthermore, it features the Dynamic Performance Control (DPC) rear torque-vectoring differential." }, oilAndCooling: { oilSquirters: "Yes, high-flow under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement map-controlled pump.", thermostatOpening: "Electronically mapped by the ECU (ranges from 90°C to 105°C).", oilCooler: "Massive independent front-mount oil cooler." }, fuelSystem: { systemType: "Bosch High Precision Direct Injection.", maxPressure: "200 Bar (Fuel Rail). Uses two mechanical high-pressure fuel pumps.", injectors: "8x Piezo Injectors (MUST be upgraded to Index 12 to prevent hydrolock)." }, tuningLimits: { maxSafeTorqueStock: "850 Nm (The heavily reinforced ZF 6HP28X handles this brilliantly).", maxSafePowerStock: "700 hp (The S63 forged bottom end handles this safely, but high heat guarantees component failure).", maxSafeRPM: "6800 RPM", weakestLink: "Rod Bearings (Spun bearing), Valve Stem Seals (Massive oil burning), Injectors (Hydrolock), Timing Chains (Stretch), Hot-V Cooling Lines (Fire risk)." }, electrical: { coils: "Individual Coil Pack system (Bosch).", ecu: "Dual Siemens MSD85.3 (Highly tunable via OBD)." } },
