        engineeringData: { blockDesign: "V8 (90-degree), Closed-deck Aluminum block with cast iron cylinder liners. The N63 introduced the revolutionary 'Hot-V' configuration, placing the twin turbos inside the valley between the cylinders. This design traps unimaginable heat, destroying every plastic and rubber component nearby and earning it a reputation as one of the most problematic engines ever.", crankshaft: "Forged Steel, supported by 5 main bearings. Features a cross-plane design.", pistonSpeed: "15.4 m/s @ 6500 RPM.", alternator: "High-Voltage integrated Motor-Generators (No traditional alternator).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features a 10.0:1 compression ratio.", wristPinDiameter: "22 mm.", connectingRodLength: "143 mm.", rodBoltSize: "M10.", crankMainJournal: "70.0 mm.", crankRodJournal: "48.0 mm.", rodRatio: "1.73." }, cylinderHead: { combustionChamberVol: "Pent-roof design with centrally located Piezo injectors.", intakePortFlow: "32-valve DOHC design. The intake manifolds are uniquely placed on the OUTSIDE of the cylinder banks, while the exhaust ports face the INSIDE 'V'. Features Double-VANOS (variable valve timing) but notably DOES NOT feature Valvetronic.", valveSizes: "Intake: 33.0 mm / Exhaust: 29.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Highly variable via Double-VANOS.", lifterType: "Hydraulic bucket tappets.", specialFeature: "The Two-Mode ActiveHybrid System. The E72 X6 is an incredibly rare, hyper-complex hybrid vehicle. It combines the 407hp N63 V8 with a massive 'Two-Mode' transmission co-developed with GM. This transmission contains two electric motors (91hp and 86hp) and three planetary gearsets. The vehicle can drive on pure electric power up to 60 km/h, but the entire system adds a massive 200kg to the vehicle's weight and is notoriously unreliable." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement map-controlled pump.", thermostatOpening: "Electronically mapped by the ECU (ranges from 90°C to 105°C).", oilCooler: "Massive integrated liquid-to-liquid heat exchanger." }, fuelSystem: { systemType: "Bosch High Precision Direct Injection.", maxPressure: "200 Bar (Fuel Rail). Uses two mechanical high-pressure fuel pumps.", injectors: "8x Piezo Injectors (MUST be upgraded to Index 11/12 to prevent hydrolock)." }, tuningLimits: { maxSafeTorqueStock: "780 Nm (The complex Two-Mode transmission is maxed out here).", maxSafePowerStock: "485 hp (Tuning the ActiveHybrid X6 is highly discouraged due to the fragility of the hybrid drivetrain).", maxSafeRPM: "6500 RPM", weakestLink: "Two-Mode Transmission (Unrepairable), NiMH Battery Pack (Degradation), Valve Stem Seals (Massive oil burning), Injectors (Hydrolock), Timing Chains (Stretch/Snap)." }, electrical: { coils: "Individual Coil Pack system (Bosch).", ecu: "Dual Bosch MEVD17.2 + Hybrid Control Units." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent catastrophic engine hydrolock, fires, timing chain failure, and oil burning on the notoriously fragile N63 V8 engine, before the hybrid system inevitably fails.", parts: [ { category: "Valve Stem Seal Kit", brand: "Elring / Victor Reinz", note: "CRITICAL: Fixes massive blue smoke. Must use AGA Tools." }, { category: "Index 11/12 Injectors", brand: "Genuine BMW", note: "CRITICAL: Upgrade immediately to prevent engine hydrolock." }, { category: "Hot-V Turbo Cooling Lines", brand: "Genuine BMW / Billet", note: "CRITICAL: Plastic 'T' fittings crack. Upgrade to billet aluminum." }, { category: "Timing Chain Kit", brand: "Genuine BMW / IWIS", note: "CRITICAL: Replaces weak original chains to prevent snapping." }, { category: "Oil Filter Housing Gasket (OFHG)", brand: "Genuine BMW", note: "CRITICAL: Fixes oil leak that causes fatal belt ingestion." }, { category: "105Ah AGM Battery", brand: "Varta / Genuine BMW", note: "CRITICAL: Supports the massive 12V system load." }, { category: "Spark Plugs", brand: "NGK SILZKBR8D8S", note: "Requires 8 units. Specific to N63." }, { category: "Front Thrust Arms (Control Arms)", brand: "Lemförder", note: "Fixes severe E72 braking shimmy caused by the massive hybrid chassis weight." } ] },
